Here is the code to set up the particle system.

```javascript
// script.js
let particles = [];
const MAX_PARTICLES = 15; // Number of particles emitted per burst

class Particle {
    constructor(x, y) {
        this.position = createVector(x, y);
        // Give random initial velocity pointing outward
        this.velocity = p5.Vector.random2D();
        // Scale velocity to ensure they shoot out strongly
        this.velocity.mult(random(3, 8)); 
        this.acceleration = createVector(0, 0.1); // Slight downward pull (gravity)
        this.lifespan = 255;
        this.size = random(3, 6);
    }

    // Update particle position and velocity
    update() {
        this.velocity.add(this.acceleration);
        this.velocity.limit(15); // Keep speed from getting too high
        this.position.add(this.velocity);
        this.lifespan -= 3; // Fade effect
    }

    // Display the particle
    show() {
        stroke(255, 150, 0, this.lifespan); // Orange color fading out
        strokeWeight(this.size);
        point(this.position.x, this.position.y);
    }

    // Check if the particle is still alive
    isFinished() {
        return this.lifespan < 0;
    }
}

// Function to spawn a burst of particles from the mouse position
function spawnParticles() {
    // We spawn up to MAX_PARTICLES particles
    for (let i = 0; i < MAX_PARTICLES; i++) {
        // Spawn particle at the current mouse coordinates
        particles.push(new Particle(mouseX, mouseY));
    }
}

function setup() {
    // p5 initializes the canvas to fullscreen by default if running correctly
    createCanvas(windowWidth, windowHeight);
    background(0);
    // Set angle for smoother random vectors if needed, but random2D handles it.
}

function draw() {
    // Draw a semi-transparent background to create a fading trail effect
    background(0, 0, 0, 50); 

    // Interaction: Spawn particles when the mouse moves
    // This ensures continuous emission as the user moves the cursor.
    if (mouseIsPressed || mouseMoved) {
        // Control the spawn rate slightly
        if (frameCount % 3 === 0) { 
            spawnParticles();
        }
    }

    // 1. Update and Show all particles
    for (let i = particles.length - 1; i >= 0; i--) {
        let p = particles[i];
        p.update();
        p.show();

        // 2. Remove dead particles
        if (p.isFinished()) {
            particles.splice(i, 1);
        }
    }
}

// Handle window resizing to maintain fullscreen effect
function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}
